    # Create a dictionary to store the nodes with two incident edges
    nodes_with_two_edges = set()
    # Create a dictionary to store the edges
    new_edges = {}

    for u, v in edges:
        if (u, v) in new_edges:
            new_edges[(u, v)] -= 2
        elif (v, u) in new_edges:
            new_edges[(v, u)] -= 2
        else:
            if u > v:
                u, v = v, u
            if (u, v) in nodes_with_two_edges:
                new_edges[(u, v)] = 2
            else:
                nodes_with_two_edges.add((u, v))
                new_edges[(u, v)] = 1

    # If there are nodes with two incident edges, it's impossible to create a new graph
    if nodes_with_two_edges:
        return "-1"

    return '\n'.join([f"{u} {v}" for u, v in new_edges.keys()])

