import sys

def find_parent(parent, i):
    if parent[i] == i:
        return i
    parent[i] = find_parent(parent, parent[i])
    return parent[i]

def union_parent(parent, a, b):
    a = find_parent(parent, a)
    b = find_parent(parent, b)
    if a < b:
        parent[a] = b
    else:
        parent[b] = a

def is_bridging_edge(u, v, parent, mst_edges):
    a, b = find_parent(parent, u), find_parent(parent, v)
    return a != b and (a, b) in mst_edges

def create_new_graph(n, m, edges):
    mst_edges = set()
    parent = {}
    for i in range(1, n + 1):
        parent[i] = i
    for u, v in edges:
        if is_bridging_edge(u, v, parent, mst_edges):
            union_parent(parent, u, v)
            mst_edges.add((u, v))
    new_edges = []
    for _ in range(m):
        u, v = mst_edges.pop()
        new_edges.append((u, v))
    return new_edges

