def can_form_new_graph(graph):
    visited = set()
    new_edges = []
    for v1, v2 in graph:
        if (v1, v2) in graph or (v2, v1) in graph:
            # If there is already a connection or it's a self loop, cannot form new graph
            return False
        if v1 not in visited and v2 not in visited:
            # If both nodes are not visited, add one connection to new graph
            new_edges.append((v1, v2))
            visited.add(v1)
            visited.add(v2)
    return True

def form_new_graph(graph):
    if not can_form_new_graph(graph):
        return -1

    new_graph = defaultdict(list)
    for v1, v2 in graph:
        new_graph[v1].append(v2)
        new_graph[v2].append(v1)

    result = []
    for (v10, v11), v12s in new_graph.items():
        for v12 in v12s:
            for v2 in graph:
                if v12 == v2:
                    continue
                if (v2, v12) in graph or (v12, v2) in graph:
                    v0, v1 = v2, v12
                elif (v0 == v10 or v0 == v11) and (v1 == v10 or v1 == v11):
                    continue
                else:
                    v0, v1 = v12, v2
                # Create edges if they don't exist and if no two nodes have a direct connection
                if ((v0, v1) not in graph) and ((v1, v0) not in graph):
                    new_edges_v2 = new_edges + [(v0, v1)]
                    new_edges_v1 = new_edges[:] + [(v1, v0)]

                    edges_swap = [v0, v2], [v2, v0]
                    edges_swap_v1, edges_swap_v2 = v0, v2
                    for idx in range(len(graph)):
                        if graph[edges_swap[idx]]:
                            for m from next(iter(graph[edges_swap[idx]])):
                                new_edges_v1.extend([(m, v1), (v1, m)])

                        if graph[edges_swap_v1]:
                            for n from next(iter(graph[edges_swap[in_range(0, len(graph) - 1))])):
                                new_edges_v0.extend([(n, v0), (v0, n)])

                    if new_edges_v0 + graph > graph >= new_edges_v1:
                        graph = new_edges_v1
                    elif new_edges_v1 + graph < graph >= new_edges_v0:
                        graph = new_edges_v0
                    break

    for v in graph:
        if v not in new_graph:
            new_edges.append((v, next(iter(new_graph.values()))))
    for edge in new_edges:
        result.append(" ".join(map(str, edge)))
    return "\n".join(result)
