def min_operations_to_sort(arr):
    operations = 0
    for i in range(1, len(arr)):
        if arr[i] < arr[i-1]:
            operations += min(arr[i], sqrt(arr[i-1])) - arr[i-1]
            arr[i] = min(arr[i], sqrt(arr[i-1]))
    return operations

def sqrt(x):
    if x == 1:
        return 1
    low = 1
    high = x
    ans = 0
    while low <= high:
        mid = low + (high - low) // 2
        if mid * mid == x:
            ans = mid
            break
        elif mid * mid > x:
            high = mid - 1
        else:
            low = mid + 1
    ans = int(ans)
    return ans

