def find_max_power_of_2(n, S):
    for x in range(n+1, -1, -1):
        for mask in range(1 << x):
            if x == np.bitwise_xor(mask, mask ^ (mask >> 1)):
                return x
    return 0

def generate_magic_permutation(x, mask):
    permutation = np.array([0] * (1 << x))
    permutation[mask] = 1
    last = 0
    for i in range(1, (1 << x) - 1):
        if mask & (1 << i):
            mask ^= (1 << i)
            last += 1
        else:
            mask ^= (1 << last)
            last += 1
        permutation[mask] = last
    return permutation.tolist()

