from collections import defaultdict
from queue import Queue

def is_possible(graph, threshold):
    # Initialize the graph
    n = len(graph)
    edges = set()

    # Ensure that the number of nodes matches
    if n != threshold:
        return False

    # Ensure every node has at most two connections
    for u, v in graph:
        if len(graph[u]) + len(graph[v]) > 2:
            return False

    # Simply check for one-to-one connections (Link1 to Link2 - same connections as Link2 to Link1)
    for u in graph:
        for v in graph[u]:
            if len(graph[u]) == 1 and graph[u].pop():
                return False

    return True

def add_edges_with_threshold(graph, threshold):
    new_graph = defaultdict(list)
    for u, vs in graph.items():
        for v in vs:
            if len(new_graph[u]) == threshold:
                break
            new_graph[u].append(v)
        else:
            continue
        return get_edges_for_nodes(graph, u, vs, new_graph)

def get_edges_for_nodes(graph, start, touched, new_graph):
    queue = Queue()
    touch = set()
    edges = set()

    touched.add(start)
    output = [start,]
    while len(touched) < len(graph):
        node = touched.pop()
        output.append(node)

        queue.put(node)

        while not queue.empty() and len(touched) < threshold:
            node = queue.get()
            touch.add(node)
            for v in new_graph[node]:
                if v not in touched and v not in touch:
                    edges.add((node, v))
                    touched.add(v)
            queue.queue.clear()

    return edges

def construct_new(graph, threshold):
    if not is_possible(graph, threshold):
        return -1

    add_edges_with_threshold(graph, threshold)
    return [f"{u} {v}" for u, vs in graph.items() for v in vs]

