def min_time_to_open_next_box(n, w, levels):
    dp = [[float('inf')] * 3 for _ in range(n+1)]
    dp[0][0], dp[0][1], dp[0][2] = 0, levels[0][1] - levels[0][0], 0
    for i in range(1, n+1):
        for j in range(3):
            if j == 0:
                dp[i][j] = dp[i-1][j]
            elif j == 1:
                dp[i][j] = min(dp[i-1][2], levels[i-1][1] - levels[i-1][0]) + dp[i-1][0]
            else:
                dp[i][j] = min(dp[i-1][1], dp[i-1][2]) + levels[i-1][1] - levels[i-1][0]
    return dp[n][0]
