from itertools import permutations

def calculate_happiness(s1, s2, s3, s4):
    # Concatenate the strings in the required order
    candidate = s1 + s2 + s3 + s4
    # Count the frequency of each character
    char_count = [0] * 5
    for char in candidate:
        if char == '0':
            char_count[0] += 1
        elif char == '1':
            char_count[1] += 1
    # Calculate the maximum number of [substrings] S1 can be partitioned into
    max_side = min(1 + char_count[1] // 2, 1 + char_count[0] // 2)
    return max_side

def find_max_happiness(s, queries):
    # Initialize the answer with the integral beauty of S
    postfix_beauty = int(s[0], 2)
    for i in range(1, len(s)):
        if i % 2 == 0:
            # Split the string whenever you have more 1's than 0's
            for lst in permutations(s[0:(i+1)//2 + 1], (i+1)//2 + 1):
                inter_beauty = 0
                for j in range(i + 1, len(s)):
                    inter_beauty += calculate_happiness('', ''.join(lst), s[j-1], '')
                if inter_beauty > postfix_beauty:
                    postfix_beauty = inter_beauty
    return postfix_beauty

