from typing import List, Set
from collections import defaultdict, deque

def max_profit(n: int, edges: List[int], direct_w: List[int], special: Set[int]) -> List[int]:
    graph = defaultdict(list)
    for x, y in edges:
        graph[x].append(y)
        graph[y].append(x)

    def bfs(start: int, visited: Set[int], queue: List[int]):
        visited.add(start)
        while queue:
            node = queue.pop()
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

    def max_profit_for_saturation(target: int, marks: Set[int]) -> int:
        """Returns the maximum profit to make 'mark' saturated."""
        max_profit = 0
        queue = deque([target])  # Starting node is already visited.
        visited = set([target])
        while queue:
            curr = queue.popleft()
            for neighbor in graph[curr]:
                if neighbor not in visited:
                    max_profit = max(max_profit, c[neighbor] - direct_w[neighbor])
                    queue.append(neighbor)
        return max_profit

    c = [float('-inf')] * (n + 1)
    for i in range(1, n + 1):
        if i in marks:
            node = i
            while node in graph:
                c[target] = max(c[target], max_profit(node, {i}, [target]))
                c[i] = max(c[i], max_profit(node, {target}, [node]))
                for neighbor in graph[node]:
                    if neighbor != target:
                        c[neighbor] = max(c[neighbor], max_profit(neighbor, {target, node}, [i]))
                node = graph[node][0]

    return list(c.values())
