def construct_new_graph(n, m, edges):
    if m < 2 * n - 2 or m > n * (n - 1) // 2:
        return "-1"

    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u - 1].append(v - 1)
        graph[v - 1].append(u - 1)

    new_graph = [[] for _ in range(n)]

    available_edges = set()
    for u, adj in enumerate(graph):
        for v in adj:
            available_edges.add((u, v))

    nodes_left = n
    for _ in range(n - 2):
        u, v = min(available_edges, key=lambda x: len(graph[x[0]]) + len(graph[x[1]]))
        new_graph[u].append(v)
        nodes_left -= 1
        if nodes_left == 1:
            break
        available_edges.remove((u, v))

    for u in range(n):
        if len(new_graph[u]) > 2:
            return "-1"

    new_graph_str = "\n".join(" ".join(map(str, edge)) for edge in new_graph)
    return new_graph_str


n, m = map(int, input().split())
edges = [list(map(int, input().split())) for _ in range(m)]

print(construct_new_graph(n, m, edges))
